@js:(function(){
var id = cache.getFromMemory("music_id");
var cachedUrl = cache.getFromMemory("music_audio_" + id);
if (cachedUrl) {
    java.log("使用缓存的音频地址: " + cachedUrl);
    return cachedUrl;
}

java.log("=== 获取新的音频地址 ===");
var playId = cache.getFromMemory("play_id");

let url = `https://www.gequbao.com/api/play-url,{"method": "post","body": "id=${playId}"}`;
var res = java.ajax(url);

var audioUrl = java.getString("$.data.url", res);
java.log("获取到音频地址: " + audioUrl);

// 缓存地址
cache.putMemory("music_audio_" + id, audioUrl);
return audioUrl;
})();

