@js:(function() {
var id = cache.getFromMemory("music_id");
result = cache.getFromMemory("music_text_" + id);
if (result) return result;
var texts = java.getStringList("//div[@id='content-lrc']/text()");
var result = '';
let len = texts.size() - 1;
for (var i = 0; i < len; i++) {
    result += texts.get(i);
    result += '\n';
}
result += texts.get(len);
cache.putMemory("music_text_" + id, result);
return result;
})();
